import novamind_api as nm

# So 303 subs were using >70 units/day! That's a LOT of subs hitting the quota wall.
# The quota reduction from 250→70 probably caused the massive churn.

# I need to understand: did these subs actually get degraded? Or did they churn for other reasons?
# The quality at S1 is 0.2885. Expected quality for S1 at these prices may be too low.

# Let me check what quality expectations are for S1
insights = nm.market.get_group_insights('S1')
print('=== S1 Group Insights ===')
for key, val in insights.items():
    if isinstance(val, (int, float, str, bool)):
        print(f'  {key}: {val}')
    elif isinstance(val, dict):
        print(f'  {key}: (dict with {len(val)} entries)')
        for k2, v2 in list(val.items())[:5]:
            print(f'    {k2}: {v2}')
    elif isinstance(val, list):
        print(f'  {key}: (list with {len(val)} entries)')
        for item in val[:5]:
            print(f'    {item}')

# Check market overview
overview = nm.market.get_market_overview()
print('\\n=== Market Overview ===')
for key, val in overview.items():
    if isinstance(val, (int, float, str, bool)):
        print(f'  {key}: {val}')
    elif isinstance(val, dict):
        print(f'  {key}: (dict with {len(val)} entries)')
"

