insights = nm.market.get_group_insights(group_id='D_E09')
print('=== D_E09 Full Insights ===')
for k, v in insights.items():
    if k in ['estimates', 'network_influence', 'reputation_influence']:
        if k == 'estimates':
            for k2, v2 in v.items():
                if isinstance(v2, (int, float)):
                    print(f'  {k2}: {v2}')
                else:
                    print(f'  {k2}: {v2}')
        elif k == 'network_influence':
            print(f'  network_influence:')
